import {createWorld,parseWorld,validateWorld,analyzeWorld,worldForSharing} from './game-core.mjs';
import {mountBuilder,renderWorldSvg} from './builder.mjs';

const $=id=>document.getElementById(id);
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const read=(key,fallback,storage=localStorage)=>{try{return JSON.parse(storage.getItem(key))??fallback;}catch{return fallback;}};
const readArray=key=>{const value=read(key,[]);return Array.isArray(value)?value:[];};
const write=(key,value,storage=localStorage)=>{try{storage.setItem(key,JSON.stringify(value));return true;}catch{toast('浏览器空间不足，请导出已有作品后再保存。');return false;}};
const compact=world=>worldForSharing(world);
// Archive identifiers are local labels, not authentication credentials. LAN
// HTTP pages may not expose crypto.randomUUID, unlike localhost/HTTPS.
const localId=()=>globalThis.crypto?.randomUUID?.()??`space-${Date.now().toString(36)}-${Math.random().toString(36).slice(2)}`;
function roomDraftKey(credentials){return `hahaisland.draft.v1:room:${credentials.id}:player:${credentials.playerId}`;}
function loadDraft(credentials){const value=read(credentials?roomDraftKey(credentials):'hahaisland.draft.v1',null);return {world:parseWorld(value),scopedValid:!!credentials&&validateWorld(value)};}
const storedCredentials=read('hahaisland.room.v1',null,sessionStorage);
const credentials=storedCredentials&&['id','token','playerId'].every(key=>typeof storedCredentials[key]==='string')?storedCredentials:null;
const initialDraft=loadDraft(credentials);
const storedProfile=read('hahaisland.profile.v1',null);
const profile=storedProfile&&typeof storedProfile.nickname==='string'?{nickname:storedProfile.nickname.slice(0,20),avatar:storedProfile.avatar==='female'?'female':'male'}:{nickname:'建造者 07',avatar:'male'};
const state={profile,loggedIn:!!storedProfile,mode:credentials?'coop':'solo',theme:'forest',world:initialDraft.world,hasScopedDraft:initialDraft.scopedValid,roomDraftHydrated:false,room:null,credentials,rooms:[],roomLatency:null,connection:'正在连接共创服务…',roomsLoaded:false,roomQuery:'',view:'',archiveIndex:0,guesses:{},lastResult:null,reportRecord:null,flipped:false};
const settings={sound:false,reduceMotion:false,...read('hahaisland.settings.v1',{})};
const names={desert:'沙漠绿洲',snow:'雪山村落',forest:'森林瀑布',city:'未来城市'};
const typeNames={INFP:'调停者',ISTP:'鉴赏家',ENFP:'竞选者',INTJ:'建筑师',ENTP:'辩论家',INFJ:'提倡者',ISFJ:'守卫者',ESFP:'表演者',INTP:'逻辑学家',ENTJ:'指挥官',ENFJ:'主人公',ISTJ:'物流师',ISFP:'探险家',ESTP:'企业家',ESTJ:'总经理',ESFJ:'执政官'};
const types=Object.keys(typeNames);
let assets={},builderCleanup=null,frame=null,toastTimer,worldSaveTimer,pollBusy=false,roomListBusy=false,audioContext;
const storedArchive=read('hahaisland.archive.v1',[]),storedPeople=read('hahaisland.people.v1',[]);
let archive=(Array.isArray(storedArchive)?storedArchive:[]).filter(record=>record&&validateWorld(record.world)).slice(0,20);
let savedPeople=Array.isArray(storedPeople)?storedPeople.filter(person=>person&&typeof person.id==='string'):[];

function toast(message){$('space-toast').textContent=message;$('space-toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('space-toast').hidden=true,3600);}
function asset(group,key){return assets[group]?.[key]??'';}
function avatarImage(value=state.profile.avatar){return value==='female'?asset('rooms','imgEllipse1'):asset('login','imgEllipse');}
function characterImage(value=state.profile.avatar){return value==='female'?asset('character','img'):asset('character','img1');}
function identityImage(type,avatar=state.profile.avatar){const keys={INFP:'img',ISTP:'img1',ENFP:'img2',INTJ:'img3',ENTP:'img4',INFJ:'img5',ISFJ:'img6',ESFP:'img7'};return keys[type]?asset('result',keys[type]):characterImage(avatar);}
function button(label,action,kind='primary',attrs=''){return `<button type="button" class="${kind}" data-action="${action}" ${attrs}>${label}</button>`;}
function go(view){if(location.hash===`#${view}`)render();else location.hash=view;}
function showDialog(title,body){$('dialog-content').innerHTML=`<h2 id="dialog-title">${title}</h2>${body}`;if(!$('space-dialog').open)$('space-dialog').showModal();}
function applySettings(){document.body.classList.toggle('reduce-motion',!!settings.reduceMotion);}
function clickSound(){if(!settings.sound)return;try{audioContext??=new AudioContext();const oscillator=audioContext.createOscillator(),gain=audioContext.createGain();oscillator.connect(gain);gain.connect(audioContext.destination);oscillator.frequency.value=520;gain.gain.setValueAtTime(.025,audioContext.currentTime);gain.gain.exponentialRampToValueAtTime(.001,audioContext.currentTime+.08);oscillator.start();oscillator.stop(audioContext.currentTime+.08);}catch{}}
function saveProfile(){state.loggedIn=true;write('hahaisland.profile.v1',state.profile);}
function saveDraft(world){state.world=world;const cooperative=state.mode==='coop'&&state.credentials;if(cooperative)state.hasScopedDraft=true;write(cooperative?roomDraftKey(state.credentials):'hahaisland.draft.v1',world);}
function currentAnalysis(){const record=archive[0];const world=analyzeWorld(state.world).counts.occupied?state.world:record?.world;return world?analyzeWorld(world):null;}
function chrome(view){
  if(view==='route'||view==='build')return '';
  return `<header class="site-header"><a class="site-brand" href="#home">空间性格<small>HahaIsland</small></a><nav class="header-links" aria-label="主导航">${view==='login'?'<span>在建造中认识自己与彼此</span>':`<a href="#route">城市漫步 ↗</a><a class="header-profile" href="#profile"><img src="${avatarImage()}" alt=""><span>${esc(state.profile.nickname)}</span></a>`}</nav></header>`;
}
function homeView(){
  const aux=[['个人主页','回顾我的空间记录','imgUser','profile'],['游戏说明','了解建造与共创规则','imgBookOpen','help'],['世界地图','探索四种岛屿主题','imgMap','map'],['设置','调整声音与体验偏好','imgSettings','settings']];
  return `<section class="page home-page" data-node-id="168:14759"><div class="home-wrap"><div class="home-intro"><h1>在建造中认识自己，也认识彼此。</h1><p>空间是媒介，行为是线索。选择一条属于你的探索路径。</p></div><div class="mode-cards"><article class="mode-card"><h2>自创模式</h2><p>在一座属于自己的岛上，<br>搭建你的精神空间。</p><div class="mode-illustration"><img src="${asset('home','img')}" alt="在一座属于自己的岛上建造精神空间"></div>${button('开始搭建　→','solo')}</article><article class="mode-card"><h2>共创模式</h2><p>与同行的玩家在同一片空间里，<br>共同建造，互相观察与猜测。</p><div class="mode-illustration"><div class="forest-preview"><img src="${asset('home','img1')}" alt="森林瀑布共创岛屿"></div></div>${button('创建 / 加入房间　→','coop','neutral')}</article></div><div class="home-aux">${aux.map(([title,description,key,action])=>`<button class="aux-card" data-action="${action}"><strong><img src="${asset('home',key)}" alt="">${title}</strong><span>${description}</span></button>`).join('')}</div></div></section>`;
}
function loginView(){return `<section class="page login-page" data-node-id="168:14758"><img class="login-scene" src="${asset('scene','img')}" alt=""><div class="login-copy"><h1>每一次搭建，<br>都是一种表达。</h1><p>创造空间，留下痕迹。在这里认识自己，也认识彼此。</p></div><form class="login-form" id="login-form"><h2>准备出发</h2><div class="avatar-picker"><button type="button" class="login-avatar" data-action="avatar" aria-label="更换头像"><img id="login-avatar-image" src="${avatarImage()}" alt="当前头像"></button><button type="button" class="text-button" data-action="avatar">更换头像</button></div><label class="form-field">玩家昵称<input name="nickname" aria-label="玩家昵称" value="${esc(state.profile.nickname)}" maxlength="20" required autocomplete="nickname"></label><p class="form-status" id="login-status" role="status"></p><button class="primary" type="submit">开始探索</button>${button('游客进入','guest','neutral')}</form></section>`;}
function themesView(){return `<section class="page themes-page"><nav class="world-tabs" aria-label="世界地图类型"><a href="#themes" class="active">岛屿世界</a><a href="#route">城市漫步</a></nav><div class="world-stage">${Object.entries(names).map(([key,name],i)=>`<button class="island-option ${state.theme===key?'selected':''}" data-action="theme-${key}" aria-pressed="${state.theme===key}"><span class="island-crop q${i}"><img src="${asset('theme','img')}" alt=""></span><strong>${name}</strong></button>`).join('')}<div class="world-boat"><img src="${asset('theme','img1')}" alt=""><img src="${asset('theme','img2')}" alt="地图中央的小船"></div><div class="world-caption"><h1>选择${state.mode==='coop'?'共创':'自己的'}岛屿</h1><p>${state.mode==='coop'?'选一处风景，邀请朋友共同建造。':'四种风景，一段属于你的空间探索。'}</p>${button('前往 '+names[state.theme]+'　→','theme-confirm')}</div></div><a class="quiet theme-back" href="#home">← 返回首页</a></section>`;}
function characterView(){const choice=(avatar,label)=>`<button class="character-option ${state.profile.avatar===avatar?'selected':''}" data-action="character-${avatar}" aria-pressed="${state.profile.avatar===avatar}"><img src="${characterImage(avatar)}" alt="${label}"><strong>${label}</strong><small>${state.profile.avatar===avatar?'● 已选中':'选择这个形象'}</small></button>`;return `<section class="page character-page"><div class="character-stage">${choice('female','女生基础形象')}<div class="character-center"><img class="${state.flipped?'flipped':''}" src="${characterImage()}" alt="选中的基础角色预览"><div class="character-rotate">${button('←','flip','', 'aria-label="镜像查看角色"')}${button('→','flip','','aria-label="镜像查看角色"')}</div></div>${choice('male','男生基础形象')}</div><div class="wide page-bottom"><a href="#themes" class="quiet">← 返回</a>${button('确认角色','character-confirm')}</div><p class="character-note">基础形象不预设人格类型 · 箭头切换正面镜像预览</p></section>`;}
function roomRows(){const rooms=state.rooms.filter(room=>room.name.toLowerCase().includes(state.roomQuery.toLowerCase()));if(!rooms.length)return `<div class="empty-panel"><h2>${state.roomsLoaded?'还没有发现房间':'正在寻找共创伙伴'}</h2><p>${esc(state.connection)}${state.roomsLoaded?' 创建一间自己的房间，或先体验自创模式。':''}</p>${button('创建房间','create-room')}${button('先去自创','solo','quiet')}</div>`;return `<div class="room-table-head"><span></span><span>群组名称</span><span>玩家人数</span><span>请求延迟</span><span>状态</span><span></span></div>${rooms.map(room=>{const available=room.status==='waiting'&&room.count<room.capacity;return `<article class="room-row"><img src="${avatarImage('male')}" alt=""><div><h2>${esc(room.name)}</h2><small>${esc(names[room.theme]??room.theme)} · ${esc(room.id)}</small></div><span>${room.count} / ${room.capacity}</span><span>${state.roomLatency??'—'} ms</span><span class="${available?'available':''}">${available?'可加入':room.status==='waiting'?'房间已满':room.status==='building'?'建造中':'已结束'}</span>${button(available?'加入':'不可加入',`join-${room.id}`,'primary',available?'':'disabled')}</article>`;}).join('')}`;}
function roomsView(){return `<section class="page rooms-page wide"><div class="rooms-head"><div><h1>寻找共创伙伴</h1><p>创建或加入四人 / 八人会话，一起探索空间留下的性格线索。</p></div><div class="rooms-head-actions">${button('↻ 重新搜索','refresh-rooms','neutral')}${button('创建房间 ＋','create-room')}</div></div><div class="rooms-search"><input id="room-search" aria-label="搜索房间名称" placeholder="搜索房间名称" value="${esc(state.roomQuery)}"><span class="caption">${esc(names[state.theme])} · 同一服务中的实时房间</span></div><div id="rooms-list" class="rooms-list" aria-live="polite">${roomRows()}</div><div class="network-status"><span id="network-state" class="${state.roomsLoaded?'connected':''}">${esc(state.connection)}</span><span>列表每 2 秒更新，延迟是本次请求实测值。</span></div><div class="page-bottom"><a class="neutral" href="#home">← 返回首页</a>${state.credentials?button('返回我的房间','resume-room','quiet'):''}</div></section>`;}
function lobbyView(){const room=state.room;if(!room)return `<section class="page rooms-page wide"><div class="empty-panel"><h2>尚未进入房间</h2><p>${esc(state.connection)}</p><a href="#rooms" class="primary">寻找共创伙伴</a></div></section>`;const me=room.players.find(p=>p.id===state.credentials?.playerId);const allReady=room.players.every(p=>p.ready&&p.online!==false);return `<section class="page lobby-page"><div class="lobby-heading"><h1>${esc(room.name)}</h1><p>${room.players.length} / ${room.capacity}　<span class="caption">玩家已进入</span></p><small>${esc(names[room.theme]??room.theme)} · 房间 ${esc(room.id)} · ${room.status==='waiting'?'等待伙伴就绪':room.status==='building'?'正在建造':'建造已结束'}</small></div><div class="seats">${Array.from({length:room.capacity},(_,i)=>{const player=room.players[i];return player?`<article class="seat"><div class="seat-avatar"><img src="${characterImage(player.avatar)}" alt="${player.avatar==='female'?'女生':'男生'}角色"></div><strong>${esc(player.nickname)}${player.id===me?.id?' · 你':''}</strong><span>${player.online===false?'暂时离线':player.finished?'已完成':player.ready?'已就绪':'等待准备'}${player.host?' · 房主':''}</span><small>${String(i+1).padStart(2,'0')} / 建设区域</small></article>`:`<article class="seat empty"><div class="seat-avatar"><img src="${asset('lobby','imgFrame')}" alt=""></div><strong>虚位以待</strong><span>等待加入</span><small>席位 ${String(i+1).padStart(2,'0')}</small></article>`;}).join('')}</div><div class="wide page-bottom">${button('退出房间','leave-room','neutral')}<div class="lobby-actions">${room.status==='waiting'?`${button(me?.ready?'取消准备':'我已准备', 'toggle-ready','neutral')}${me?.host?button('开始游戏','start-room','primary',allReady?'':'disabled'): '<span class="caption">等待房主开始</span>'}`:button(room.status==='building'?'继续建造':'查看结算',room.status==='building'?'resume-build':'results')}</div></div><p class="wide caption" id="room-status" role="status">${esc(state.connection)}</p></section>`;}
function dimensionMarkup(analysis){const dimensions=analysis?.dimensions;const labels=[['I 内向','E 外向','#d8397a'],['S 实感','N 直觉','#d79b18'],['T 思考','F 情感','#149fd0'],['P 开放','J 稳定','#478d54']];return `<div class="dimension-list">${labels.map(([left,right,color],i)=>{const value=dimensions?.[i];const known=Number.isFinite(value);const title=known?(value>=.5?right:left):'等待建造';const percent=known?Math.round((value>=.5?value:1-value)*100):null;return `<div class="dimension" style="--dimension-color:${color};--value:${known?value*100:50}%"><div class="dimension-heading"><strong>${left}</strong><span class="dimension-value">${title} ${known?percent+'%':'—'}</span><span>${right}</span></div><div class="dimension-track">${'<i></i>'.repeat(20)}${known?'<b class="dimension-marker"></b>':''}</div><span class="dimension-number">${known?value.toFixed(2):'—'}</span></div>`;}).join('')}<div class="dimension-scale"><span>0</span><span>0.5</span><span>1</span></div></div>`;}
function profileView(){const analysis=currentAnalysis(),type=analysis?.type;return `<section class="page profile-page wide"><div class="profile-grid"><div class="identity-panel"><p>${analysis?'本局空间线索':'还没有空间记录'} / ${esc(state.profile.nickname)}</p><img src="${identityImage(type)}" alt="${type?'空间形象 '+type:'基础角色形象'}"><div class="identity-name"><strong>${type??'—'}</strong><span>${type?typeNames[type]:'等待你的表达'}</span></div><p class="identity-caption">${analysis?esc(analysis.description):'搭建第一块体块，留下自己的空间痕迹。'}</p></div><article class="dimensions-card"><h1>我的空间性格</h1><p>每一次建造，都是认识自己的线索。</p>${dimensionMarkup(analysis)}<p class="caption">由实际建造行为生成的游戏指标，描述本局空间，不代表心理测评。</p><p class="caption">已保存 ${archive.length} 个空间 · 城市漫步记录 ${readArray('hahaisland.walks.v1').length} 次</p></article></div><div class="page-bottom"><a href="#archive" class="quiet">我的空间档案</a>${button('开始游玩 →','solo')}</div></section>`;}
function archiveView(){const record=archive[state.archiveIndex%Math.max(1,archive.length)];if(!record)return `<section class="page archive-page"><div class="archive-wrap"><h1>共创空间档案</h1><p class="subtitle">保存空间作品，回顾每一次选择留下的痕迹。</p><div class="empty-panel"><h2>这里，等待你的第一个空间。</h2><p>完成一次建造后，作品和真实行为指标会保存在这里。</p>${button('开始搭建 →','solo')}</div><div class="page-bottom"><a href="#profile" class="quiet">← 返回我的主页</a></div></div></section>`;const a=analyzeWorld(record.world),d=a.dimensions;return `<section class="page archive-page"><div class="archive-wrap"><h1>共创空间档案</h1><p class="subtitle">保存空间作品，回顾每一次选择留下的痕迹。</p><div class="archive-stack" id="archive-stack">${Array.from({length:Math.min(4,archive.length-1)},()=>'<div class="archive-layer"></div>').join('')}<article class="archive-current"><div class="archive-preview">${renderWorldSvg(record.world,{label:record.name,id:'archive'})}</div><div class="archive-copy"><h2>${esc(record.name)}<small>${esc(new Date(record.createdAt).toLocaleDateString('zh-CN'))}</small></h2><p>${record.mode==='coop'?'共创作品':'自创作品'} / ${esc(names[record.theme]??record.theme)} · ${record.players?.length??1} 位同行者</p><p class="archive-dimensions">E ${Math.round(d[0]*100)}% / I ${Math.round((1-d[0])*100)}%　 S ${Math.round((1-d[1])*100)}% / N ${Math.round(d[1]*100)}%<br>T ${Math.round((1-d[2])*100)}% / F ${Math.round(d[2]*100)}%　 J ${Math.round(d[3]*100)}% / P ${Math.round((1-d[3])*100)}%</p><p>${esc(a.description)}<br>保留 ${a.counts.edits} 次编辑行为线索。</p>${button('回顾本局空间报告','archive-report')}</div><div class="archive-controls">${button('‹','archive-prev','','aria-label="上一个作品"')}<span>${state.archiveIndex+1} / ${archive.length}　滑动浏览更多作品</span>${button('›','archive-next','','aria-label="下一个作品"')}</div></article></div><div class="page-bottom"><a class="quiet" href="#profile">← 返回我的主页</a>${button('导出当前作品 ↓','export-world','quiet')}</div></div></section>`;}
function participants(){if(state.reportRecord)return state.reportRecord.players?.length?state.reportRecord.players:[{id:'local',...state.profile,world:state.reportRecord.world}];if(state.mode==='coop'&&state.room)return state.room.players.map(p=>({...p,world:p.id===state.credentials?.playerId?state.world:state.room.worlds[p.id]}));return [{id:'local',...state.profile,world:state.lastResult?.world??state.world}];}
function isMe(player){return player.id==='local'||player.id===state.credentials?.playerId||player.id===state.reportRecord?.selfId;}
function guessView(){const peers=participants().filter(p=>!isMe(p));return `<section class="page guess-page wide"><h1>从空间，认识同行的人。</h1><p class="subtitle">观察伙伴真实建造的空间，留下你的空间类型猜想。</p><div class="guess-cards">${peers.length?peers.map(p=>`<article class="guess-card"><h2>${esc(p.nickname)}</h2><div class="guess-preview">${validateWorld(p.world)?renderWorldSvg(p.world,{label:p.nickname,id:p.id}):'<p class="caption">伙伴的空间还在建造中…</p>'}</div><label class="form-field">你的猜想<select data-peer="${esc(p.id)}" aria-label="猜测${esc(p.nickname)}的空间类型"><option value="">暂不猜测</option>${types.map(type=>`<option value="${type}" ${state.guesses[p.id]===type?'selected':''}>${type} · ${typeNames[type]}</option>`).join('')}</select></label><p class="caption">这是游戏中的空间观察，不为真实人格下定义。</p></article>`).join(''):`<div class="empty-panel"><h2>这一次，先认识自己的空间。</h2><p>自创模式无需互猜。你也可以创建房间，邀请朋友一起建造。</p></div>`}</div><div class="page-bottom"><a href="#build" class="quiet">← 返回我的空间</a>${button('保存观察，揭晓空间线索 →','reveal')}</div></section>`;}
function resultsView(){const people=participants();return `<section class="page results-page wide"><h1>空间里的我们</h1><p class="subtitle">每一位同行者，都留下了不一样的表达。</p><div class="results-grid">${people.map(p=>{const valid=validateWorld(p.world)&&analyzeWorld(p.world).counts.occupied>0,a=valid?analyzeWorld(p.world):null,guess=state.guesses[p.id],mine=isMe(p);return `<article class="result-card"><h2>${esc(p.nickname)}${mine?' · 你':''}</h2><div class="result-costume"><img src="${identityImage(a?.type,p.avatar)}" alt="${a?.type??'基础'}角色形象"></div><div class="result-type"><strong>${a?.type??'—'}</strong><span>${a?typeNames[a.type]:'等待建造'}</span></div><strong>${mine?'我的空间线索':guess?`${guess===a?.type?'观察一致':'另一种理解'} · 猜想 ${guess}`:'尚未留下猜想'}</strong><p>已布置地块 ${a?.counts.occupied??0} / 36</p><p>建造模块 ${a?.counts.floors??0} · 编辑 ${a?.counts.edits??0} 次</p><div class="result-actions">${button('查看详情',`report-${p.id}`,'quiet')}${mine?'<a class="primary" href="#profile">我的主页</a>':button(savedPeople.some(x=>x.id===p.id)?'已收藏':'收藏同伴 ＋',`person-${p.id}`)}</div></article>`;}).join('')}</div><p class="result-notice">${people.length} 位真实参与者 · 类型由本局建造统计生成，仅作游戏中的空间表达。</p><div class="results-footer"><a class="quiet" href="#profile">返回我的主页</a><a class="quiet" href="#archive">查看最终岛屿</a>${button('再玩一局 →','solo')}</div></section>`;}
function render(){
  const next=(location.hash.slice(1)||(!state.loggedIn?'login':'home')).split('?')[0];
  const valid=['login','home','themes','character','rooms','lobby','build','profile','archive','guess','results','route'];
  const view=valid.includes(next)?next:'home';
  builderCleanup?.();builderCleanup=null;state.view=view;
  $('page-chrome').innerHTML=chrome(view);$('view').hidden=view==='route';$('route-view').hidden=view!=='route';document.body.classList.toggle('route-active',view==='route');
  document.title=`${({login:'准备出发',home:'空间性格',themes:'世界地图',character:'选择角色',rooms:'寻找共创伙伴',lobby:'等待伙伴',build:'我的空间',profile:'个人主页',archive:'空间档案',guess:'观察与猜想',results:'空间里的我们',route:'城市漫步'})[view]} · HahaIsland`;
  if(view==='route'){openRoute();return;}
  const views={login:loginView,home:homeView,themes:themesView,character:characterView,rooms:roomsView,lobby:lobbyView,profile:profileView,archive:archiveView,guess:guessView,results:resultsView};
  if(view==='build'){
    $('view').innerHTML='<section class="page builder-page" id="builder-host"></section>';
    const coop=state.mode==='coop'&&state.room&&state.credentials;
    builderCleanup=mountBuilder($('builder-host'),{world:state.world,mode:coop?'coop':'solo',nickname:state.profile.nickname,playerId:state.credentials?.playerId,capacity:state.room?.capacity??8,players:coop?participants():[],onChange:world=>{saveDraft(world);if(coop)scheduleWorldSave();},onFinish:finishWorld,onBack:()=>go(coop?'lobby':'themes'),onHelp:showHelp});
  }else $('view').innerHTML=views[view]();
  if(view==='rooms')refreshRooms();
  if(view==='lobby'&&state.credentials)pollRoom();
  if(view==='login')$('login-form').onsubmit=submitLogin;
  if(view==='archive'){let x;$('archive-stack')?.addEventListener('touchstart',e=>x=e.touches[0].clientX,{passive:true});$('archive-stack')?.addEventListener('touchend',e=>{const d=e.changedTouches[0].clientX-x;if(Math.abs(d)>40)moveArchive(d<0?1:-1);},{passive:true});}
  window.scrollTo({top:0,behavior:'instant'});
}
function openRoute(){if(!frame){frame=document.createElement('iframe');frame.src='./route/index.html';frame.title='斓图 · 城市漫步路线规划';frame.addEventListener('load',sendRouteOpen);$('route-host').append(frame);}else sendRouteOpen();}
function sendRouteOpen(){frame?.contentWindow?.postMessage({type:'hahaisland:route-open',nickname:state.profile.nickname},location.origin);}
window.addEventListener('message',event=>{
  if(!frame||event.origin!==location.origin||event.source!==frame.contentWindow)return;
  const message=event.data;if(!message||typeof message!=='object')return;
  if(message.type==='hahaisland:route-ready')sendRouteOpen();
  if(message.type==='hahaisland:route-close')go('home');
  if(message.type==='hahaisland:route-selected'&&Number.isFinite(message.route?.length))write('hahaisland.lastRoute.v1',{route:message.route,answers:message.answers});
  if(message.type==='hahaisland:walk-finished'&&typeof message.walkId==='string'){const walks=readArray('hahaisland.walks.v1').filter(w=>w&&typeof w.walkId==='string');if(!walks.some(w=>w.walkId===message.walkId))write('hahaisland.walks.v1',[...walks,message].slice(-40));toast('城市漫步体验已保存到个人记录。');}
});
function submitLogin(event){event.preventDefault();const nickname=new FormData(event.target).get('nickname').trim();if(!nickname||/[\u0000-\u001f\u007f]/.test(nickname)){$('login-status').textContent='请输入 1–20 个字符的昵称。';return;}state.profile.nickname=nickname.slice(0,20);saveProfile();go('home');}
function startFlow(mode){state.mode=mode;state.reportRecord=null;state.lastResult=null;state.guesses={};go('themes');}
function showHelp(){showDialog('在建造中认识自己与彼此',`<ol class="help-steps"><li>选择岛屿和基础角色，在自己的 6 × 6 地块上搭建空间。</li><li>建筑、灰空间、景观与留白都可以组合；双击地块打开精细编辑，选择形体、窗、树和颜色。</li><li>修改会自动保存。完成建造后查看四维空间线索，或观察伙伴真实的作品并互猜。</li><li>从“城市漫步”进入海淀路网，独立选择四维偏好和时间，规划实际步行路线。</li></ol><p>共创房间显示同一服务中的真实玩家。空间类型仅用于游戏表达，不代表心理测评。</p><a class="inline-link" href="./explore.html">打开原版校园地图与 NPC 任务 →</a>`);}
function showSettings(){showDialog('声音与体验偏好',`<label class="setting-row">操作提示音<input type="checkbox" name="sound" ${settings.sound?'checked':''}></label><label class="setting-row">减少动画效果<input type="checkbox" name="reduceMotion" ${settings.reduceMotion?'checked':''}></label><p class="caption">昵称、作品和漫步记录保存在当前浏览器。共创房间仅在服务运行期间保留。</p><div class="form-actions">${button('更换昵称 / 头像','edit-profile','neutral')}${button('导出所有空间','export-all','quiet')}</div>`);}
async function api(pathname,{method='GET',body,auth=false}={}){let response;try{response=await fetch('/api/rooms'+pathname,{method,headers:{...(body?{'Content-Type':'application/json'}:{}),...(auth&&state.credentials?{Authorization:`Bearer ${state.credentials.token}`}:{})},...(body?{body:JSON.stringify(body)}:{}),signal:AbortSignal.timeout(6000)});}catch{throw Error('共创服务暂时未连接，仍可继续自创。');}const contentType=response.headers.get('content-type')??'';if(!contentType.includes('application/json'))throw Error('共创服务尚未启动，仍可继续自创。');const data=await response.json();if(!response.ok){const error=Error(data.error??data.message??'请求未完成');error.status=response.status;throw error;}return data;}
async function refreshRooms(){if(roomListBusy)return;roomListBusy=true;try{const start=performance.now(),data=await api('');state.roomLatency=Math.round(performance.now()-start);state.rooms=data.rooms;state.connection='● 共创服务已连接';state.roomsLoaded=true;}catch(error){state.rooms=[];state.roomsLoaded=true;state.connection=error.message;}finally{roomListBusy=false;if(state.view==='rooms'){$('rooms-list').innerHTML=roomRows();$('network-state').textContent=state.connection;$('network-state').classList.toggle('connected',state.connection.includes('已连接'));}}}
function keepCredentials(data){state.credentials={id:data.room.id,token:data.token,playerId:data.playerId};write('hahaisland.room.v1',state.credentials,sessionStorage);state.mode='coop';state.room=data.room;state.roomDraftHydrated=true;state.hasScopedDraft=false;state.theme=data.room.theme;state.world=createWorld();saveDraft(state.world);state.reportRecord=null;go('lobby');}
function createRoomDialog(){showDialog('创建一间共创房间',`<form id="create-room-form"><label class="form-field">房间名称<input name="name" value="${esc(state.profile.nickname)}的岛" maxlength="40" required></label><label class="form-field">玩家席位<select name="capacity"><option value="8">8 人</option><option value="4">4 人</option></select></label><p class="caption">岛屿主题：${esc(names[state.theme])}。朋友访问同一服务地址后，即可发现房间。</p><p class="form-status" id="create-room-status" role="status"></p><div class="form-actions"><button class="primary" type="submit">创建房间</button></div></form>`);$('create-room-form').onsubmit=async event=>{event.preventDefault();const button=event.target.querySelector('[type=submit]');button.disabled=true;try{const form=new FormData(event.target),data=await api('',{method:'POST',body:{name:form.get('name').trim(),nickname:state.profile.nickname,avatar:state.profile.avatar,capacity:+form.get('capacity'),theme:state.theme}});$('space-dialog').close();keepCredentials(data);}catch(error){$('create-room-status').textContent=error.message;}finally{button.disabled=false;}};}
async function joinRoom(id){try{const data=await api(`/${id}/join`,{method:'POST',body:state.profile});keepCredentials(data);}catch(error){toast(error.message);refreshRooms();}}
async function roomAction(action,body){if(!state.credentials)return;const data=await api(`/${state.credentials.id}/${action}`,{method:action==='world'?'PATCH':'POST',body,auth:true});if(data.room)state.room=data.room;return data;}
async function leaveRoom(){try{if(state.credentials)await roomAction('leave',{});}catch(error){toast(error.message);}state.room=null;state.credentials=null;sessionStorage.removeItem('hahaisland.room.v1');state.mode='solo';go('rooms');}
function hydrateRoomDraft(room){
  if(state.roomDraftHydrated||!state.credentials)return;
  state.roomDraftHydrated=true;
  const own=room.worlds?.[state.credentials.playerId];
  // A scoped local draft, including edits made before this response, retains
  // its complete undo history. Other players' worlds never become our draft.
  if(state.mode==='coop'&&!state.hasScopedDraft)saveDraft(validateWorld(own)?parseWorld(own):createWorld());
  const me=room.players.find(player=>player.id===state.credentials.playerId);
  if(me)state.profile={nickname:me.nickname,avatar:me.avatar};
}
async function pollRoom(){
  if(pollBusy||!state.credentials)return;pollBusy=true;
  try{
    const previous=state.room?.version,previousStatus=state.room?.status,hadRoom=!!state.room,previousPlayers=JSON.stringify(state.room?.players);
    const data=await api(`/${state.credentials.id}`,{auth:true});
    state.room=data.room;state.connection='● 共创服务已连接';hydrateRoomDraft(data.room);
    const playersChanged=previousPlayers!==JSON.stringify(data.room.players);
    // Auto-enter when a waiting session starts, or on first rehydration. An
    // explicit return from the builder must leave the lobby exit reachable.
    if(state.view==='lobby'&&data.room.status==='building'&&(previousStatus==='waiting'||!hadRoom)&&!data.room.players.find(p=>p.id===state.credentials.playerId)?.finished){state.mode='coop';go('build');}
    else if(state.view==='lobby'&&(previous!==data.room.version||playersChanged))render();
    else if(state.view==='build'&&!hadRoom&&state.mode==='coop')render();
    if(builderCleanup&&state.mode==='coop')builderCleanup.updatePlayers?.(participants());
    if(state.view==='guess'&&previous!==data.room.version)render();
  }catch(error){
    state.connection=error.message;
    if(error.status===401||error.status===404){state.credentials=null;state.room=null;sessionStorage.removeItem('hahaisland.room.v1');toast(error.message);}
    if(state.view==='lobby'&&$('room-status'))$('room-status').textContent=state.connection;
  }finally{pollBusy=false;}
}
function scheduleWorldSave(){clearTimeout(worldSaveTimer);worldSaveTimer=setTimeout(async()=>{try{await roomAction('world',{world:compact(state.world)});}catch(error){toast('作品已在本地保存。'+error.message);}},500);}
function saveArchive(world){const people=participants().map(p=>({id:p.id,nickname:p.nickname,avatar:p.avatar,...(validateWorld(p.world)?{world:compact(p.world)}:{})}));const record={id:localId(),selfId:state.mode==='coop'?state.credentials?.playerId:'local',name:state.mode==='coop'&&state.room?state.room.name:`${state.profile.nickname}的${names[state.theme]??'岛屿'}`,createdAt:new Date().toISOString(),mode:state.mode,theme:state.theme,world:compact(world),players:people};if(write('hahaisland.archive.v1',[record,...archive].slice(0,20))){archive=[record,...archive].slice(0,20);state.archiveIndex=0;}return record;}
async function finishWorld(world){if(!analyzeWorld(world).counts.occupied){toast('先放置至少一个体块，再记录你的空间。');return;}saveDraft(world);clearTimeout(worldSaveTimer);if(state.mode==='coop'&&state.credentials){try{await roomAction('finish',{world:compact(world)});}catch(error){toast('作品已在本地保存。'+error.message);return;}}state.lastResult={world};saveArchive(world);state.reportRecord=null;go('guess');}
function moveArchive(delta){if(!archive.length)return;state.archiveIndex=(state.archiveIndex+delta+archive.length)%archive.length;render();}
function download(data,filename){const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const link=document.createElement('a');link.href=url;link.download=filename;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function showReport(player){const world=validateWorld(player?.world)?player.world:null;if(!world){showDialog('空间还在建造中','<p>伙伴尚未保存空间，请稍后再来看看。</p>');return;}const a=analyzeWorld(world);showDialog(`${esc(player.nickname)}的空间报告`,`<div class="report-grid"><div>${renderWorldSvg(world,{label:player.nickname,id:'report'})}</div><div><p>${esc(a.description)}</p><div class="stat-list">${[['建筑',a.counts.building],['灰空间',a.counts.gray],['景观',a.counts.landscape],['编辑行为',a.counts.edits]].map(([title,value])=>`<div><strong>${value}</strong><span>${title}</span></div>`).join('')}</div><p>本局空间线索：${a.counts.occupied?a.type:'—'}<br>由实际建造生成，不代表心理测评。</p></div></div>${button('关闭','close-dialog','neutral')}`);}
async function action(action){
  if(action==='solo'||action==='coop')return startFlow(action);
  if(action==='profile')return go('profile');
  if(action==='map'){state.mode='solo';return go('themes');}
  if(action==='help')return showHelp();if(action==='settings')return showSettings();
  if(action==='avatar'){state.profile.avatar=state.profile.avatar==='male'?'female':'male';$('login-avatar-image').src=avatarImage();return;}
  if(action==='guest'){state.profile.nickname='游客';saveProfile();return go('home');}
  if(action.startsWith('theme-')&&action!=='theme-confirm'){state.theme=action.slice(6);return render();}
  if(action==='theme-confirm')return go('character');
  if(action.startsWith('character-')&&action!=='character-confirm'){state.profile.avatar=action.slice(10);return render();}
  if(action==='flip'){state.flipped=!state.flipped;return render();}
  if(action==='character-confirm'){saveProfile();if(state.mode==='coop')return go('rooms');saveDraft(createWorld());return go('build');}
  if(action==='refresh-rooms')return refreshRooms();if(action==='create-room')return createRoomDialog();if(action.startsWith('join-'))return joinRoom(action.slice(5));
  if(action==='resume-room'){state.mode='coop';await pollRoom();return go('lobby');}
  if(action==='leave-room')return leaveRoom();
  if(action==='toggle-ready'){const me=state.room?.players.find(p=>p.id===state.credentials?.playerId);await roomAction('ready',{ready:!me?.ready});return render();}
  if(action==='start-room'){await roomAction('start',{});state.mode='coop';return go('build');}
  if(action==='resume-build'){state.mode='coop';return go('build');}
  if(action==='results'||action==='reveal'){if(action==='reveal')write('hahaisland.guesses.v1',state.guesses);return go('results');}
  if(action==='archive-prev')return moveArchive(-1);if(action==='archive-next')return moveArchive(1);
  if(action==='archive-report'){state.reportRecord=archive[state.archiveIndex];return go('results');}
  if(action==='export-world')return download(archive[state.archiveIndex],'hahaisland-space.json');
  if(action==='export-all')return download({exportedAt:new Date().toISOString(),spaces:archive},'hahaisland-spaces.json');
  if(action==='close-dialog')return $('space-dialog').close();
  if(action==='edit-profile'){$('space-dialog').close();return go('login');}
  if(action.startsWith('report-'))return showReport(participants().find(p=>p.id===action.slice(7)));
  if(action.startsWith('person-')){const person=participants().find(p=>p.id===action.slice(7));if(person&&!savedPeople.some(p=>p.id===person.id)){savedPeople.push({id:person.id,nickname:person.nickname,avatar:person.avatar});write('hahaisland.people.v1',savedPeople);toast('已收藏到此浏览器的同行者记录。');render();}}
}
document.addEventListener('click',event=>{const target=event.target.closest('[data-action]');if(!target||target.disabled)return;clickSound();Promise.resolve(action(target.dataset.action)).catch(error=>toast(error.message));});
document.addEventListener('input',event=>{if(event.target.id==='room-search'){state.roomQuery=event.target.value;$('rooms-list').innerHTML=roomRows();}});
document.addEventListener('change',event=>{if(event.target.dataset.peer)state.guesses[event.target.dataset.peer]=event.target.value;if(['sound','reduceMotion'].includes(event.target.name)){settings[event.target.name]=event.target.checked;write('hahaisland.settings.v1',settings);applySettings();if(event.target.name==='sound')clickSound();}});
$('space-dialog').querySelector('.dialog-close').onclick=()=>$('space-dialog').close();
document.addEventListener('keydown',event=>{if(event.target.matches('input,textarea,select')||$('space-dialog').open)return;if(state.view==='archive'&&['ArrowLeft','ArrowRight'].includes(event.key)){event.preventDefault();moveArchive(event.key==='ArrowLeft'?-1:1);}if(event.key==='Escape'&&state.view==='route')go('home');});
window.addEventListener('hashchange',render);
try{const response=await fetch('./assets/figma/manifest.json');if(!response.ok)throw Error('设计素材未能加载');assets=await response.json();if(state.credentials)state.mode='coop';applySettings();render();if(state.credentials)pollRoom();setInterval(()=>{if(state.credentials)pollRoom();if(state.view==='rooms')refreshRooms();},2000);}catch(error){$('view').innerHTML=`<section class="page rooms-page wide"><div class="empty-panel"><h2>岛屿还没准备好</h2><p>${esc(error.message)}</p><a class="primary" href="./index.html">刷新页面</a></div></section>`;console.error(error);}
